        public static Mock<ICategoryRepository> GetCategoriesRepositoryMock()
        {
            var categories = new List<Category>
            {
                new Category { CategoryId = 1, Name = "Cheese cakes", Description = "Delicious cheese cakes" },
                new Category { CategoryId = 2, Name = "Fruit pies", Description = "Tasty fruit pies" },
                new Category { CategoryId = 3, Name = "Seasonal pies", Description = "Pies for every season" }
            };
            var mockCategoryRepository = new Mock<ICategoryRepository>();
            mockCategoryRepository.Setup(repo => repo.GetAllCategories()).Returns(categories);
            return mockCategoryRepository;
        }


        private static Dictionary<string, Category> Categories = new Dictionary<string, Category>
